const markChunksStaleByFiles = `-- name: MarkChunksStaleByFiles :exec
UPDATE zdx_narrative_chunks c
SET status     = 'stale',
    updated_at = NOW()
WHERE c.project_id = $1
  AND c.status = 'fresh'
  AND c.coderef_id IN (
    SELECT cr.id FROM zdx_coderefs cr
    WHERE cr.project_id = $1
      AND cr.file = ANY($2::text[])
      AND cr.sha != $3
  )
`

type MarkChunksStaleByFilesParams struct {
	ProjectID  int32    `db:"project_id" json:"project_id"`
	Files      []string `db:"files" json:"files"`
	CurrentSha string   `db:"current_sha" json:"current_sha"`
}

func (q *Queries) MarkChunksStaleByFiles(ctx context.Context, arg MarkChunksStaleByFilesParams) error {
	_, err := q.db.Exec(ctx, markChunksStaleByFiles, arg.ProjectID, arg.Files, arg.CurrentSha)
	return err
}

